For SetProp conversions: handle value null: if target type nullable -> null; else if string -> ""; else default instance.
Convert.ChangeType for primitives with culture invariant for numeric strings — but value may already be typed (int/decimal/bool/DateTime). Handle: if target == string and value is IFormattable -> ToString(invariant). If value is string and target numeric -> parse with validators.

Implement:
```csharp
public static void SetProp(object row, string name, object value)
{
    var prop = row.GetType().GetProperty(name);
    if (prop == null || !prop.CanWrite) return;
    var type = prop.PropertyType;
    var under = Nullable.GetUnderlyingType(type) ?? type;
    object result = null;
    if (value == null || (value is string s && string.IsNullOrWhiteSpace(s) && under != typeof(string)))
    {
        result = Nullable.IsNullableType(type) ? null : (under == typeof(string) ? "" : Activator.CreateInstance(under));
    }
    else if (under.IsInstanceOfType(value)) result = value;
    else if (under == typeof(string)) result = Convert.ToString(value, CultureInfo.InvariantCulture);
    else if (under == typeof(bool) && value is string sb) result = sb=="Да"||sb=="True"||sb=="1";
    else
    {
        string text = Convert.ToString(value, CultureInfo.InvariantCulture);
        if (under == typeof(decimal)) { if (!Validators.ParseDecimal(text, out var d)) throw new FormatException(...); result=d;}
        else if (under == typeof(int)) { if(!Validators.ParseInt(text, out var i)) throw...; result=i;}
        else if (under == typeof(DateTime)) { parse; }
        else result = Convert.ChangeType(text, under, CultureInfo.InvariantCulture);
    }
    prop.SetValue(row, result);
}
```
Note Nullable.IsNullableType isn't a thing; use Nullable.GetUnderlyingType(type) != null.

DateTime parse: `DateTime.TryParse(text, CultureInfo.InvariantCulture, DateTimeStyles.None, out d)` else TryCurrentCulture else DateTime.Now? throw.

