using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using CleanPro.AppData;

namespace CleanPro.Pages
{
    public partial class AuthorizationPage : Page
    {
        public AuthorizationPage()
        {
            InitializeComponent();
        }

        private void Login_Click(object sender, RoutedEventArgs e)
        {
            txtError.Visibility = Visibility.Collapsed;

            string login = txtLogin.Text.Trim();
            string password = txtPassword.Password;

            if (login.Length == 0 || password.Length == 0)
            {
                ShowError("Заполните логин и пароль.");
                return;
            }

            try
            {
                var user = Tables.Rows<User>().FirstOrDefault(x =>
                    (x.Login == login || x.Email == login || x.Phone == login) &&
                    x.Password == password);

                if (user == null)
                {
                    ShowError("Пользователь не найден. Проверьте логин и пароль.");
                    return;
                }
                if (user.StatusId == 2)
                {
                    ShowError("Учётная запись заблокирована.");
                    return;
                }

                AppConnect.SetUser(user);
                AppConnect.Cart.Clear();
                AppFrame.mainFrame.Navigate(new CatalogPage());
            }
            catch (Exception ex)
            {
                MessageBox.Show("Не удалось войти в систему.\n" + ex.Message, "Ошибка",
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void Register_Click(object sender, RoutedEventArgs e)
        {
            AppFrame.mainFrame.Navigate(new RegistrationPage());
        }

        private void ShowError(string message)
        {
            txtError.Text = message;
            txtError.Visibility = Visibility.Visible;
        }
    }
}

using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using CleanPro.AppData;

namespace CleanPro.Pages
{
    public partial class RegistrationPage : Page
    {
        public RegistrationPage()
        {
            InitializeComponent();
        }

        private void Register_Click(object sender, RoutedEventArgs e)
        {
            txtError.Visibility = Visibility.Collapsed;

            string lastName = txtLastName.Text.Trim();
            string firstName = txtFirstName.Text.Trim();
            string login = txtLogin.Text.Trim();
            string email = txtEmail.Text.Trim();
            string phone = txtPhone.Text.Trim();
            string password = txtPassword.Password;
            string password2 = txtPassword2.Password;

            if (lastName.Length == 0 || firstName.Length == 0 || login.Length == 0 ||
                email.Length == 0 || phone.Length == 0 || password.Length == 0)
            {
                ShowError("Заполните обязательные поля, отмеченные звёздочкой.");
                return;
            }
            if (login.Length < 3)
            {
                ShowError("Логин должен содержать минимум 3 символа.");
                return;
            }
            if (!Validators.IsEmail(email))
            {
                ShowError("Некорректный Email. Пример: user@mail.ru.");
                return;
            }
            if (!Validators.IsPhone(phone))
            {
                ShowError("Некорректный телефон. Используйте 10–15 цифр, пример: +79991234567.");
                return;
            }
            if (password.Length < 6)
            {
                ShowError("Пароль должен содержать минимум 6 символов.");
                return;
            }
            if (password != password2)
            {
                ShowError("Пароли не совпадают.");
                return;
            }

            var users = Tables.Rows<User>();
            if (users.Any(x => x.Login == login))
            {
                ShowError("Такой логин уже занят.");
                return;
            }
            if (users.Any(x => x.Email == email))
            {
                ShowError("Такой Email уже используется.");
                return;
            }
            if (users.Any(x => x.Phone == phone))
            {
                ShowError("Такой телефон уже используется.");
                return;
            }

            try
            {
                var user = new User
                {
                    Id = Tables.NextId(Tables.Get("users")),
                    Login = login,
                    Password = password,
                    FirstName = firstName,
                    LastName = lastName,
                    Phone = phone,
                    Email = email,
                    Address = txtAddress.Text.Trim(),
                    RoleId = Tables.Rows<Role>().FirstOrDefault(x => x.Name == "Пользователь")?.Id ?? 2,
                    StatusId = Tables.Rows<UserStatus>().FirstOrDefault()?.Id ?? 1,
                    RegistrationDate = DateTime.Now
                };
                Tables.Add(Tables.Get("users"), user);

                AppConnect.SetUser(user);
                AppConnect.Cart.Clear();
                AppFrame.mainFrame.Navigate(new CatalogPage());
            }
            catch (Exception ex)
            {
                MessageBox.Show("Не удалось зарегистрироваться.\n" + ex.Message, "Ошибка",
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void Back_Click(object sender, RoutedEventArgs e)
        {
            AppFrame.mainFrame.Navigate(new AuthorizationPage());
        }

        private void ShowError(string message)
        {
            txtError.Text = message;
            txtError.Visibility = Visibility.Visible;
        }
    }
}

