                return;
            }
            if (!Validators.IsEmail(email))
            {
                ShowError("Некорректный Email. Пример: user@mail.ru.");
                return;
            }
            if (!Validators.IsPhone(phone))
            {
                ShowError("Некорректный телефон. Используйте 10–15 цифр.");
                return;
            }
            if (password.Length > 0 && password.Length < 6)
            {
                ShowError("Новый пароль должен содержать минимум 6 символов.");
                return;
            }
            if (password != password2)
            {
                ShowError("Пароли не совпадают.");
                return;
            }

            var users = Tables.Rows<User>();
            if (users.Any(x => x.Id != _user.Id && x.Login == login))
            {
                ShowError("Такой логин уже занят.");
                return;
            }
            if (users.Any(x => x.Id != _user.Id && x.Email == email))
            {
                ShowError("Такой Email уже используется.");
                return;
            }
            if (users.Any(x => x.Id != _user.Id && x.Phone == phone))
            {
                ShowError("Такой телефон уже используется.");
                return;
            }

            try
            {
                _user.LastName = lastName;
                _user.FirstName = firstName;
                _user.Login = login;
                _user.Email = email;
                _user.Phone = phone;
                _user.Address = txtAddress.Text.Trim();
                if (password.Length > 0) _user.Password = password;

                AppConnect.SetUser(_user);
                MessageBox.Show("Изменения сохранены.", "Готово",
                    MessageBoxButton.OK, MessageBoxImage.Information);
                AppFrame.mainFrame.Navigate(new CatalogPage());
            }
            catch (Exception ex)
