namespace CleanPro.Pages
{
    public partial class CartPage : Page
    {
        public CartPage()
        {
            InitializeComponent();

            if (AppConnect.Rank < 1)
            {
                AppFrame.mainFrame.Navigate(new AuthorizationPage());
                return;
            }

            listCart.ItemsSource = Cart.Items;
            txtAddress.Text = AppConnect.CurrentUser.Address ?? "";
            dtDate.SelectedDate = DateTime.Now.Date;
            UpdateTotal();
        }

        private void UpdateTotal()
        {
            txtTotal.Text = $"Итого: {Cart.TotalSum():N2} ₽";
        }

        private void Qty_Changed(object sender, RoutedEventArgs e)
        {
            if (!(sender is TextBox box) || !(box.DataContext is CartItem item))
                return;

            if (!Validators.ParseDecimal(box.Text, out decimal quantity) || quantity <= 0)
            {
                MessageBox.Show("Количество должно быть числом больше нуля.", "Ошибка",
                    MessageBoxButton.OK, MessageBoxImage.Warning);
                box.Text = item.Quantity.ToString();
                return;
            }

            item.Quantity = quantity;
            listCart.Items.Refresh();
            UpdateTotal();
        }

        private void Remove_Click(object sender, RoutedEventArgs e)
        {
            if (!(sender is Button button) || !(button.Tag is CartItem item))
                return;

            Cart.Items.Remove(item);
            listCart.Items.Refresh();
            UpdateTotal();
        }

        private void Clear_Click(object sender, RoutedEventArgs e)
        {
            if (Cart.Items.Count == 0) return;

            if (MessageBox.Show("Очистить корзину?", "Подтверждение",
                MessageBoxButton.YesNo, MessageBoxImage.Question) != MessageBoxResult.Yes)
                return;

            Cart.Items.Clear();
            listCart.Items.Refresh();
            UpdateTotal();
        }

        private void Back_Click(object sender, RoutedEventArgs e)
        {
            AppFrame.mainFrame.Navigate(new CatalogPage());
        }

        private void Checkout_Click(object sender, RoutedEventArgs e)
        {
            txtError.Visibility = Visibility.Collapsed;

            if (Cart.Items.Count == 0)
            {
                ShowError("Корзина пуста. Добавьте услуги в каталоге.");
                return;
            }

            string address = txtAddress.Text.Trim();
            if (address.Length == 0)
            {
                ShowError("Укажите адрес выполнения заказа.");
                return;
            }

            if (dtDate.SelectedDate == null)
            {
                ShowError("Укажите дату выполнения заказа.");
                return;
            }

            try
            {
                var orderTable = Tables.Get("orders");
                var itemsTable = Tables.Get("order-items");

                var order = new Order
                {
                    Id = Tables.NextId(orderTable),
                    Number = "ORD-" + Tables.NextId(orderTable).ToString("D6"),
                    UserId = AppConnect.CurrentUser.Id,
                    StatusId = Tables.Rows<OrderStatus>().FirstOrDefault()?.Id ?? 1,
                    OrderDate = DateTime.Now,
                    ScheduledDate = dtDate.SelectedDate.Value,
                    Address = address,
                    Comment = txtComment.Text.Trim(),
                    Total = Cart.TotalSum()
                };
                Tables.Add(orderTable, order);

                foreach (var cartItem in Cart.Items)
                {
                    Tables.Add(itemsTable, new OrderItem
                    {
                        Id = Tables.NextId(itemsTable),
                        OrderId = order.Id,
                        ServiceId = cartItem.ServiceId,
                        Quantity = cartItem.Quantity,
                        UnitPrice = cartCartPrice(cartItem),
                        FinalPrice = cartItem.Sum
                    });
                }

                Cart.Items.Clear();
                AppFrame.mainFrame.Navigate(new OrdersPage());

                MessageBox.Show($"Заказ №{order.Number} оформлен.", "Готово",
                    MessageBoxButton.OK, MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                MessageBox.Show("Не удалось оформить заказ.\n" + ex.Message, "Ошибка",
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private decimal cartCartPrice(CartItem item) => item.Price;

        private void ShowError(string message)
        {
            txtError.Text = message;
            txtError.Visibility = Visibility.Visible;
        }
    }
}

