using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using CleanPro.AppData;

namespace CleanPro.Pages
{
    public partial class EntityEditPage : Page
    {
        private readonly TableDef _table;
        private readonly object _row;
        private readonly bool _isNew;
        private readonly List<FieldControl> _controls = new List<FieldControl>();

        public EntityEditPage(TableDef table, object item)
        {
            InitializeComponent();

            _table = table;
            _isNew = item == null;
            _row = item ?? Tables.Create(table);

            txtTitle.Text = (_isNew ? "Добавление записи — " : "Изменение записи — ") + table.Title;
            BuildForm();
        }

        private void BuildForm()
        {
            foreach (var field in _table.Fields)
            {
                if (field.ReadOnly && _isNew) continue;

                AddLabel(field.Title + (field.Required ? " *" : ""));

                if (field.ReadOnly)
                {
                    formPanel.Children.Add(new TextBlock
                    {
                        Text = Tables.Display(_row, field.Name),
                        Margin = new Thickness(0, 2, 0, 8)
                    });
                    continue;
                }

                switch (field.Kind)
                {
                    case FieldKind.FK:
                        BuildCombo(field);
                        break;
                    case FieldKind.Bool:
                        BuildCheck(field);
                        break;
                    case FieldKind.Date:
                    case FieldKind.DateTime:
                        BuildDate(field);
                        break;
                    case FieldKind.Image:
                        BuildImage(field);
                        break;
                    default:
                        BuildText(field);
                        break;
                }
            }
        }

        private void AddLabel(string text)
        {
            formPanel.Children.Add(new TextBlock
            {
                Text = text,
                Style = (Style)Application.Current.Resources["FieldLabel"]
            });
        }

        private void BuildText(FieldDef field)
        {
            object current = Tables.GetProp(_row, field.Name);

            if (field.Kind == FieldKind.Password)
            {
                var box = new PasswordBox();
                if (current is string password) box.Password = password;
                if (field.MaxLength.HasValue) box.MaxHeight = 40;
                formPanel.Children.Add(box);
                _controls.Add(new FieldControl(field, box, () => box.Password));
                return;
            }

            var textBox = new TextBox();
            if (current != null) textBox.Text = Convert.ToString(current) ?? "";
            if (field.MaxLength.HasValue) textBox.MaxLength = field.MaxLength.Value;
            formPanel.Children.Add(textBox);
            _controls.Add(new FieldControl(field, textBox, () => textBox.Text));
        }

        private void BuildCheck(FieldDef field)
        {
            var check = new CheckBox { Content = "Да" };
            check.IsChecked = Tables.GetProp(_row, field.Name) is bool value && value;
            formPanel.Children.Add(check);
            _controls.Add(new FieldControl(field, check, () => check.IsChecked == true));
        }

        private void BuildDate(FieldDef field)
        {
            var picker = new DatePicker();
            object current = Tables.GetProp(_row, field.Name);
            if (current is DateTime date && date != default(DateTime)) picker.SelectedDate = date;
            formPanel.Children.Add(picker);
            _controls.Add(new FieldControl(field, picker, () => picker.SelectedDate));
        }

        private void BuildCombo(FieldDef field)
        {
            var combo = new ComboBox
            {
                ItemsSource = Options(field),
                DisplayMemberPath = field.OptionProp,
                SelectedValuePath = "Id"
            };

            int current = 0;
            object value = Tables.GetProp(_row, field.Name);
            if (value != null) current = Convert.ToInt32(value);
            if (current == 0 && !field.Required) current = 0;
            combo.SelectedValue = current == 0 ? (field.Nullable ? 0 : 0) : current;
            if (current == 0) combo.SelectedIndex = 0;

            formPanel.Children.Add(combo);
            _controls.Add(new FieldControl(field, combo, () =>
            {
                if (!(combo.SelectedItem is object selected)) return null;
                int id = Tables.GetId(selected);
                if (id == 0 && field.Nullable) return null;
                if (id == 0) return null;
                return id;
            }));
        }

        private List<object> Options(FieldDef field)
        {
            var rows = Tables.Options(field.ListKey).Cast<object>().ToList();
            if (field.Nullable)
            {
                var empty = Activator.CreateInstance(Tables.Get(field.ListKey).EntityType);
                Tables.SetProp(empty, "Id", 0);
                rows.Insert(0, empty);
            }
            return rows;
        }

        private void BuildImage(FieldDef field)
        {
            string current = Convert.ToString(Tables.GetProp(_row, field.Name)) ?? "";

            var panel = new DockPanel { Margin = new Thickness(0, 2, 0, 8) };
            var pathBox = new TextBox { IsReadOnly = true, Text = current, Margin = new Thickness(0), VerticalContentAlignment = VerticalAlignment.Center };
            DockPanel.SetDock(pathBox, DockPanel.Dock.Left);

            var browse = new Button { Content = "Обзор...", MinWidth = 90, Margin = new Thickness(6, 0, 0, 0) };
            browse.Click += (s, e) =>
            {
                string file = ImageFiles.SelectFile();
                if (file == null) return;
                try
                {
                    string path = ImageFiles.CopyToProject(file);
                    pathBox.Text = path;
                    UpdatePreview(field, path);
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Не удалось загрузить изображение.\n" + ex.Message, "Ошибка",
                        MessageBoxButton.OK, MessageBoxImage.Error);
                }
            };

            panel.Children.Add(pathBox);
            panel.Children.Add(browse);
            formPanel.Children.Add(panel);
            UpdatePreview(field, current);
            _controls.Add(new FieldControl(field, pathBox, () => pathBox.Text));
        }

        private void UpdatePreview(FieldDef field, string path)
        {
            RemovePreview();

            if (string.IsNullOrWhiteSpace(path)) return;

            var image = new Image
            {
                Height = 150,
                Margin = new Thickness(0, 6, 0, 8),
                Stretch = System.Windows.Controls.Stretch.Uniform,
                HorizontalAlignment = HorizontalAlignment.Left
            };

            try
            {
                if (path.StartsWith("/", StringComparison.Ordinal) || path.StartsWith("pack:", StringComparison.OrdinalIgnoreCase))
                    image.Source = new BitmapImage(new Uri("pack://application:,,,/" + path.TrimStart('/')));
                else
                    image.Source = new BitmapImage(new Uri(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, path), UriKind.Absolute));
            }
            catch
            {
                return;
            }

            panelTag(image);
        }

        private void RemovePreview()
        {
            for (int i = 0; i < formPanel.Children.Count; i++)
            {
                if (formPanel.Children[i] is Image image && ReferenceEquals(image.Tag, "preview"))
                {
                    formPanel.Children.RemoveAt(i);
                    return;
                }
            }
        }

        private void panelTag(Image image)
        {
            image.Tag = "preview";
            int index = formPanel.Children.Count;
            for (int i = 0; i < formPanel.Children.Count; i++)
            {
                if (formPanel.Children[i] is TextBox box && box.IsReadOnly)
                {
                    index = i + 1;
                    break;
                }
            }
            formPanel.Children.Insert(index, image);
        }

        private bool Validate()
        {
            foreach (var control in _controls)
            {
                var field = control.Field;
                object value = control.GetValue();
                string text = value as string ?? "";

                if (field.Kind == FieldKind.Text || field.Kind == FieldKind.Password ||
                    field.Kind == FieldKind.Email || field.Kind == FieldKind.Phone)
                {
                    if (field.Required && text.Trim().Length == 0)
                        return Validators.Error($"Заполните поле «{field.Title}».");
                    if (field.MaxLength.HasValue && text.Length > field.MaxLength.Value)
                        return Validators.Error($"Поле «{field.Title}» длиннее {field.MaxLength.Value} символов.");
                    if (field.Kind == FieldKind.Email && text.Length > 0 && !Validators.IsEmail(text))
                        return Validators.Error($"Поле «{field.Title}» должно содержать корректный Email.");
                    if (field.Kind == FieldKind.Phone && text.Length > 0 && !Validators.IsPhone(text))
                        return Validators.Error($"Поле «{field.Title}» должно содержать корректный телефон (10–15 цифр).");
                }

                if (field.Kind == FieldKind.Int || field.Kind == FieldKind.Decimal)
                {
                    bool empty = value == null || (value is string s && s.Trim().Length == 0);
                    if (empty)
                    {
                        if (field.Required)
                            return Validators.Error($"Заполните поле «{field.Title}».");
                        continue;
                    }

                    bool ok = field.Kind == FieldKind.Int
                        ? Validators.ParseInt(Convert.ToString(value), out _)
                        : Validators.ParseDecimal(Convert.ToString(value), out _);
                    if (!ok)
                        return Validators.Error(field.Kind == FieldKind.Int
                            ? $"Поле «{field.Title}» должно быть целым числом."
                            : $"Поле «{field.Title}» должно быть числом.");

                    decimal number = field.Kind == FieldKind.Int
                        ? int.Parse(Convert.ToString(value))
                        : ParseDecimal(value);

                    if (field.Min.HasValue && number < field.Min.Value)
                        return Validators.Error($"Поле «{field.Title}» должно быть не меньше {field.Min.Value.ToString().TrimEnd('0', '.')}.");
                    if (field.Max.HasValue && number > field.Max.Value)
                        return Validators.Error($"Поле «{field.Title}» должно быть не больше {field.Max.Value.ToString().TrimEnd('0', '.')}.");
                }

                if (field.Kind == FieldKind.Date || field.Kind == FieldKind.DateTime)
                {
                    if (field.Required && (value == null || !(value is DateTime)))
                        return Validators.Error($"Укажите поле «{field.Title}».");
                }

                if (field.Kind == FieldKind.FK && field.Required && value == null)
                    return Validators.Error($"Выберите «{field.Title}».");
            }

            if (_table.Key == "users" && !ValidateUsers()) return false;

            return true;
        }

        private bool ValidateUsers()
        {
            int id = Convert.ToInt32(Tables.GetProp(_row, "Id"));
            string login = Convert.ToString(Tables.GetProp(_row, "Login")) ?? "";
            string email = Convert.ToString(Tables.GetProp(_row, "Email")) ?? "";
            string phone = Convert.ToString(Tables.GetProp(_row, "Phone")) ?? "";
            var users = Tables.Rows<User>();

            if (users.Any(x => x.Id != id && x.Login == login))
                return Validators.Error("Такой логин уже занят.");
            if (users.Any(x => x.Id != id && x.Email == email))
                return Validators.Error("Такой Email уже используется.");
            if (users.Any(x => x.Id != id && x.Phone == phone))
                return Validators.Error("Такой телефон уже используется.");
            return true;
        }

        private decimal ParseDecimal(object value)
        {
            Validators.ParseDecimal(Convert.ToString(value), out decimal result);
            return result;
        }

        private void Save_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                if (!Validate()) return;

                foreach (var control in _controls)
                    Tables.SetProp(_row, control.Field.Name, control.GetValue());

                if (_isNew) Tables.Add(_table, _row);

                AppFrame.mainFrame.Navigate(new DataPage(_table.Key));
            }
            catch (Exception ex)
            {
                MessageBox.Show("Не удалось сохранить запись.\n" + ex.Message, "Ошибка",
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void Cancel_Click(object sender, RoutedEventArgs e)
        {
            AppFrame.mainFrame.Navigate(new DataPage(_table.Key));
        }

        private class FieldControl
        {
            public FieldDef Field { get; }
            public FrameworkElement Element { get; }
            public Func<object> GetValue { get; }

            public FieldControl(FieldDef field, FrameworkElement element, Func<object> getValue)
            {
                Field = field;
                Element = element;
                GetValue = getValue;
            }
        }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media.Imaging;
using CleanPro.AppData;

namespace CleanPro.Pages
{
    public partial class EntityEditPage : Page
    {
        private readonly TableDef _table;
        private readonly object _row;
        private readonly bool _isNew;
        private readonly List<FieldControl> _controls = new List<FieldControl>();
        private StackPanel _previewHost;

        public EntityEditPage(TableDef table, object item)
        {
            InitializeComponent();

            _table = table;
            _isNew = item == null;
            _row = item ?? Tables.Create(table);

            txtTitle.Text = (_isNew ? "Добавление записи — " : "Изменение записи — ") + table.Title;
            BuildForm();
        }

        private void BuildForm()
        {
            foreach (var field in _table.Fields)
            {
                if (field.ReadOnly && _isNew) continue;

                AddLabel(field.Title + (field.Required ? " *" : ""));

                if (field.ReadOnly)
                {
                    formPanel.Children.Add(new TextBlock
                    {
                        Text = Tables.Display(_row, field.Name),
                        Margin = new Thickness(0, 2, 0, 8)
                    });
                    continue;
                }

                switch (field.Kind)
                {
                    case FieldKind.FK:
                        BuildCombo(field);
                        break;
                    case FieldKind.Bool:
                        BuildCheck(field);
                        break;
                    case FieldKind.Date:
                    case FieldKind.DateTime:
                        BuildDate(field);
                        break;
                    case FieldKind.Image:
                        BuildImage(field);
                        break;
                    default:
                        BuildText(field);
                        break;
                }
            }
        }

        private void AddLabel(string text)
        {
            formPanel.Children.Add(new TextBlock
            {
                Text = text,
                Style = (Style)Application.Current.Resources["FieldLabel"]
            });
        }

        private void BuildText(FieldDef field)
        {
            object current = Tables.GetProp(_row, field.Name);

            if (field.Kind == FieldKind.Password)
            {
                var box = new PasswordBox();
                if (current is string password) box.Password = password;
                formPanel.Children.Add(box);
                _controls.Add(new FieldControl(field, () => box.Password));
                return;
            }

            var textBox = new TextBox();
            if (current != null) textBox.Text = Convert.ToString(current) ?? "";
            if (field.MaxLength.HasValue) textBox.MaxLength = field.MaxLength.Value;
            formPanel.Children.Add(textBox);
            _controls.Add(new FieldControl(field, () => textBox.Text));
        }

        private void BuildCheck(FieldDef field)
        {
            var check = new CheckBox { Content = "Да" };
            check.IsChecked = Tables.GetProp(_row, field.Name) is bool value && value;
            formPanel.Children.Add(check);
            _controls.Add(new FieldControl(field, () => check.IsChecked == true));
        }

        private void BuildDate(FieldDef field)
        {
            var picker = new DatePicker();
            object current = Tables.GetProp(_row, field.Name);
            if (current is DateTime date && date != default(DateTime)) picker.SelectedDate = date;
            formPanel.Children.Add(picker);
            _controls.Add(new FieldControl(field, () => picker.SelectedDate));
        }

        private void BuildCombo(FieldDef field)
        {
            var combo = new ComboBox
            {
                ItemsSource = Options(field),
                DisplayMemberPath = field.OptionProp,
                SelectedValuePath = "Id"
            };

            object value = Tables.GetProp(_row, field.Name);
            if (value != null)
                combo.SelectedValue = Convert.ToInt32(value);
            else
                combo.SelectedIndex = -1;

            formPanel.Children.Add(combo);
            _controls.Add(new FieldControl(field, () =>
            {
                if (!(combo.SelectedItem is object selected)) return null;
                int id = Tables.GetId(selected);
                return id == 0 ? null : (object)id;
            }));
        }

        private List<object> Options(FieldDef field)
        {
            var rows = Tables.Options(field.ListKey).Cast<object>().ToList();
            if (field.Nullable)
            {
                var empty = Activator.CreateInstance(Tables.Get(field.ListKey).EntityType);
                Tables.SetProp(empty, "Id", 0);
                rows.Insert(0, empty);
            }
            return rows;
        }

        private void BuildImage(FieldDef field)
        {
            string current = Convert.ToString(Tables.GetProp(_row, field.Name)) ?? "";

            var row = new DockPanel { Margin = new Thickness(0, 2, 0, 0) };
            var pathBox = new TextBox
            {
                IsReadOnly = true,
                Text = current,
                Margin = new Thickness(0),
                VerticalContentAlignment = VerticalAlignment.Center
            };
            DockPanel.SetDock(pathBox, DockPanel.Dock.Left);

            var browse = new Button
            {
                Content = "Обзор...",
                MinWidth = 90,
                Margin = new Thickness(6, 0, 0, 0)
            };
            browse.Click += (s, e) =>
            {
                string file = ImageFiles.SelectFile();
                if (file == null) return;
                try
                {
                    string path = ImageFiles.CopyToProject(file);
                    pathBox.Text = path;
                    UpdatePreview(path);
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Не удалось загрузить изображение.\n" + ex.Message, "Ошибка",
                        MessageBoxButton.OK, MessageBoxImage.Error);
                }
            };

            row.Children.Add(pathBox);
            row.Children.Add(browse);
            formPanel.Children.Add(row);

            _previewHost = new StackPanel();
            formPanel.Children.Add(_previewHost);
            UpdatePreview(current);

            _controls.Add(new FieldControl(field, () => pathBox.Text));
        }

        private void UpdatePreview(string path)
        {
            if (_previewHost == null) return;

            _previewHost.Children.Clear();
            if (string.IsNullOrWhiteSpace(path)) return;

            var image = new Image
            {
                Height = 160,
                Stretch = Stretch.Uniform,
                HorizontalAlignment = HorizontalAlignment.Left,
                Margin = new Thickness(0, 6, 0, 4)
            };

            try
            {
                if (path.StartsWith("/") || path.StartsWith("pack:", StringComparison.OrdinalIgnoreCase))
                    image.Source = new BitmapImage(new Uri("pack://application:,,,/" + path.TrimStart('/')));
                else
                    image.Source = new BitmapImage(new Uri(
                        System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, path),
                        UriKind.Absolute));
            }
            catch
            {
                return;
            }

            _previewHost.Children.Add(image);
        }

        private bool Validate()
        {
            foreach (var control in _controls)
            {
                var field = control.Field;
                object value = control.GetValue();
                string text = value as string ?? "";

                if (field.Kind == FieldKind.Text || field.Kind == FieldKind.Password ||
                    field.Kind == FieldKind.Email || field.Kind == FieldKind.Phone)
                {
                    if (field.Required && text.Trim().Length == 0)
                        return Validators.Error($"Заполните поле «{field.Title}».");
                    if (field.MaxLength.HasValue && text.Length > field.MaxLength.Value)
                        return Validators.Error($"Поле «{field.Title}» длиннее {field.MaxLength.Value} символов.");
                    if (field.Kind == FieldKind.Email && text.Length > 0 && !Validators.IsEmail(text))
                        return Validators.Error($"Поле «{field.Title}» должно содержать корректный Email.");
                    if (field.Kind == FieldKind.Phone && text.Length > 0 && !Validators.IsPhone(text))
                        return Validators.Error($"Поле «{field.Title}» должно содержать корректный телефон (10–15 цифр).");
                }

                if (field.Kind == FieldKind.Int || field.Kind == FieldKind.Decimal)
                {
                    bool empty = value == null || (value is string s && s.Trim().Length == 0);
                    if (empty)
                    {
                        if (field.Required)
                            return Validators.Error($"Заполните поле «{field.Title}».");
                        continue;
                    }

                    bool isNumber = field.Kind == FieldKind.Int
                        ? Validators.ParseInt(Convert.ToString(value), out _)
                        : Validators.ParseDecimal(Convert.ToString(value), out _);
                    if (!isNumber)
                        return Validators.Error(field.Kind == FieldKind.Int
                            ? $"Поле «{field.Title}» должно быть целым числом."
                            : $"Поле «{field.Title}» должно быть числом.");

                    decimal number = field.Kind == FieldKind.Int
                        ? int.Parse(Convert.ToString(value))
                        : ParseDecimal(value);

                    if (field.Min.HasValue && number < field.Min.Value)
                        return Validators.Error($"Поле «{field.Title}» должно быть не меньше {field.Min.Value}.");
                    if (field.Max.HasValue && number > field.Max.Value)
                        return Validators.Error($"Поле «{field.Title}» должно быть не больше {field.Max.Value}.");
                }

                if ((field.Kind == FieldKind.Date || field.Kind == FieldKind.DateTime) &&
                    field.Required && !(value is DateTime))
                {
                    return Validators.Error($"Укажите поле «{field.Title}».");
                }

                if (field.Kind == FieldKind.FK && field.Required && value == null)
                    return Validators.Error($"Выберите «{field.Title}».");
            }

            if (_table.Key == "users" && !ValidateUsers()) return false;

            return true;
        }

        private bool ValidateUsers()
        {
            int id = Convert.ToInt32(Tables.GetProp(_row, "Id"));
            string login = ControlValue("Login");
            string email = ControlValue("Email");
            string phone = ControlValue("Phone");
            var users = Tables.Rows<User>();

            if (users.Any(x => x.Id != id && x.Login == login))
                return Validators.Error("Такой логин уже занят.");
            if (users.Any(x => x.Id != id && x.Email == email))
                return Validators.Error("Такой Email уже используется.");
            if (users.Any(x => x.Id != id && x.Phone == phone))
                return Validators.Error("Такой телефон уже используется.");
            return true;
        }

        private string ControlValue(string fieldName)
        {
            var control = _controls.FirstOrDefault(x => x.Field.Name == fieldName);
            return control == null ? "" : Convert.ToString(control.GetValue()) ?? "";
        }

        private decimal ParseDecimal(object value)
        {
            Validators.ParseDecimal(Convert.ToString(value), out decimal result);
            return result;
        }

        private void Save_Click(object sender, RoutedEventArgs e)
        {
            try
            {
                if (!Validate()) return;

                foreach (var control in _controls)
                    Tables.SetProp(_row, control.Field.Name, control.GetValue());

                if (_isNew) Tables.Add(_table, _row);

                AppFrame.mainFrame.Navigate(new DataPage(_table.Key));
            }
            catch (Exception ex)
            {
                MessageBox.Show("Не удалось сохранить запись.\n" + ex.Message, "Ошибка",
                    MessageBoxButton.OK, MessageBoxImage.Error);
            }
        }

        private void Cancel_Click(object sender, RoutedEventArgs e)
        {
            AppFrame.mainFrame.Navigate(new DataPage(_table.Key));
        }

        private class FieldControl
        {
            public FieldDef Field { get; }
            public Func<object> GetValue { get; }

            public FieldControl(FieldDef field, Func<object> getValue)
            {
                Field = field;
                GetValue = getValue;
            }
        }
    }
}

