}
'@
Add-Type -TypeDefinition $src

$UIA = [System.Windows.Automation]

function Get-AppElement {
    $proc = Get-Process CleanPro -ErrorAction SilentlyContinue
    if (-not $proc) { throw 'app not running' }
    [U]::SetWindowPos($proc.MainWindowHandle, [IntPtr]::new(-1), 0, 0, 1400, 900, 0x0040) | Out-Null
    [U]::SetForegroundWindow($proc.MainWindowHandle) | Out-Null
    Start-Sleep -Milliseconds 350
    return $UIA::AutomationElement::FromHandle($proc.MainWindowHandle)
}
function Find-Id($id, $root) {
    if (-not $root) { $root = Get-AppElement }
    $cond = New-Object $UIA::PropertyCondition($UIA::AutomationElement::AutomationIdProperty, $id)
    return $root.FindFirst($UIA::TreeScope::Descendants, $cond)
}
function Find-Button($name, $root) {
    if (-not $root) { $root = Get-AppElement }
    $c1 = New-Object $UIA::PropertyCondition($UIA::AutomationElement::ControlTypeProperty, [System.Windows.Automation.ControlType]::Button)
    $c2 = New-Object $UIA::PropertyCondition($UIA::AutomationElement::NameProperty, $name)
    $cond = New-Object $UIA::AndCondition($c1, $c2)
    return $root.FindFirst($UIA::TreeScope::Descendants, $cond)
}
function Set-Val($el, $value) {
    $p = $el.GetCurrentPattern($UIA::ValuePattern::Pattern)
    $p.SetValue($value)
}
function Set-Text($id, $value, $root = $null) {
    $el = Find-Id $id $root
    if (-not $el) { throw "no element $id" }
    Set-Val $el $value
}
function Invoke-Id($id, $root = $null) {
    $el = Find-Id $id $root
    if (-not $el) { throw "no element $id" }
    $p = $el.GetCurrentPattern($UIA::InvokePattern::Pattern)
    $p.Invoke()
}
function Invoke-Button($name, $root = $null) {
    $el = Find-Button $name $root
    if (-not $el) { throw "no button $name" }
    $p = $el.GetCurrentPattern($UIA::InvokePattern::Pattern)
    $p.Invoke()
}
function Select-Index($id, $index, $root = $null) {
    $el = Find-Id $id $root
    if (-not $el) { throw "no element $id" }
    $cond = New-Object $UIA::PropertyCondition($UIA::AutomationElement::ControlTypeProperty, [System.Windows.Automation.ControlType]::ListItem)
    $items = $el.FindAll($UIA::TreeScope::Descendants, $cond)
    $item = $items.Item($index)
    if (-not $item) { throw "no item $index" }
    $p = $item.GetCurrentPattern($UIA::SelectionItemPattern::Pattern)
    $p.Select()
}
function Select-Grid-Text($gridId, $text, $root = $null) {
    $grid = Find-Id $gridId $root
    if (-not $grid) { throw "no grid $gridId" }
    $types = @([System.Windows.Automation.ControlType]::Row, [System.Windows.Automation.ControlType]::DataItem, [System.Windows.Automation.ControlType]::ListItem)
    foreach ($t in $types) {
        $cond = New-Object $UIA::PropertyCondition($UIA::AutomationElement::ControlTypeProperty, $t)
        $rows = $grid.FindAll($UIA::TreeScope::Descendants, $cond)
        for ($i = 0; $i -lt $rows.Count; $i++) {
            $name = $rows.Item($i).Current.Name
            if ($name -like "*$text*") {
                $p = $rows.Item($i).GetCurrentPattern($UIA::SelectionItemPattern::Pattern)
                $p.Select()
                return $true
            }
        }
    }
    return $false
}
function Get-Text($id, $root = $null) {
    $el = Find-Id $id $root
    if (-not $el) { return "" }
    $p = $el.GetCurrentPattern($UIA::ValuePattern::Pattern)
    return $p.Current.Value
}
function Shot($out) {
    $root = Get-AppElement
    Start-Sleep -Milliseconds 350
    $bmp = New-Object System.Drawing.Bitmap 1400, 900
    $g = [System.Drawing.Graphics]::FromImage($bmp)
    $g.CopyFromScreen((New-Object System.Drawing.Point 0, 0), (New-Object System.Drawing.Point 0, 0), (New-Object System.Drawing.Size 1400, 900))
    $bmp.Save($out, [System.Drawing.Imaging.ImageFormat]::Png)
    $g.Dispose()
    $bmp.Dispose()
    return $out
}

