function Select-Grid-Index($gridId, $index) {
    $res = Get-Grid-Rows $gridId
    $rows = $res[0]
    if ($null -eq $rows) { throw "no rows in $gridId" }
    Write-Output ('rows=' + $rows.Count + ' type=' + $res[1])
    $row = $rows.Item($index)
    $p = $row.GetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern)
    $p.Select()
}
function Select-Combo($id, $text) {
    $el = Find-Id $id
    if ($null -eq $el) { throw "no combo $id" }
    $exp = $el.GetCurrentPattern([System.Windows.Automation.ExpandCollapsePattern]::Pattern)
    $exp.Expand()
    Start-Sleep -Milliseconds 500
    $cond = New-Object System.Windows.Automation.PropertyCondition ([System.Windows.Automation.AutomationElement]::ControlTypeProperty), ([System.Windows.Automation.ControlType]::ListItem)
    $items = $el.FindAll([System.Windows.Automation.TreeScope]::Descendants, $cond)
    $found = $false
    for ($i = 0; $i -lt $items.Count; $i++) {
        if ($items.Item($i).Current.Name -like "*$text*") {
            $p = $items.Item($i).GetCurrentPattern([System.Windows.Automation.SelectionItemPattern]::Pattern)
            $p.Select()
            $found = $true
            break
        }
    }
    try { $exp.Collapse() } catch { }
    if (-not $found) { throw "no combo item $text" }
    Start-Sleep -Milliseconds 300
}

