function Set-FileDialog($value) {
    $root = [System.Windows.Automation.AutomationElement]::RootElement
    $cond = New-Object System.Windows.Automation.PropertyCondition ([System.Windows.Automation.AutomationElement]::ClassNameProperty), '#32770'
    $dlg = $root.FindFirst([System.Windows.Automation.TreeScope]::Children, $cond)
    if ($null -eq $dlg) { throw 'file dialog not found' }
    $editCond = New-Object System.Windows.Automation.PropertyCondition ([System.Windows.Automation.AutomationElement]::ControlTypeProperty), ([System.Windows.Automation.ControlType]::Edit)
    $edit = $dlg.FindFirst([System.Windows.Automation.TreeScope]::Descendants, $editCond)
    if ($null -eq $edit) { throw 'file dialog edit not found' }
    Set-Val $edit $value
    foreach ($btnName in @('Open', 'Открыть')) {
        $btn = Find-Button $btnName $dlg
        if ($null -ne $btn) {
            $p = $btn.GetCurrentPattern([System.Windows.Automation.InvokePattern]::Pattern)
            $p.Invoke()
            return
        }
    }
    throw 'open button not found'
}

